    );
  }
}

String? cekSandi(String? v) {
  final sandi = v ?? '';
  if (sandi.isEmpty) return 'Kata sandi wajib diisi';
  if (sandi.length < 8) return 'Kata sandi minimal 8 karakter (sekarang ${sandi.length})';
  return null;
}

